17	// ---- Settings write controls (passthrough, upstream proxy, backup config, pools) --------------
18	//
19	// Every write here is a two-step reviewed call: the confirm step builds the EXACT API call from
20	// the form, holds it server-side in the review map, and renders a review sheet whose projection
21	// is derived from the held bytes. The run step spends the entry atomically (LoadAndDelete),
22	// compares the submitted token in constant time, and dispatches the held call verbatim - the run
23	// form carries only the review id and token, so nothing typed after the review can change what
24	// is written.
25	//
26	// Two token mechanics sit under that one flow, because the confirm gate (needsConfirmation in
27	// agent_tools.go) covers riskScope and above while the passthrough, upstream-proxy and backup
28	// routes are riskLocal and ungated:
29	//   - pools (riskScope): the token is minted by the confirmation gate, bound to the exact call's
30	//     method, path, query and body digest (confirm_binding.go), and the run dispatches through
31	//     the guarded chain with the token in the confirm header - the same flow the triage editor
32	//     uses for its riskCredential PUT.
33	//   - passthrough / proxy / backup (riskLocal, ungated): the token is a ui2-local one-use review
34	//     handle (randomHex(16)) and the run dispatches through the internal mux. The exact-bytes
35	//     property is preserved by construction: the held call is dispatched verbatim and the entry
36	//     dies on any spend attempt. No gate claim is made for these routes.
37	//
38	// Scope decisions for this first write surface (independent review, 2026-10-31):
39	//   - No proxy URL or default carrying userinfo is minted on this page: an authenticated upstream
40	//     routes credentials with future traffic, and this surface has no redaction story yet. The
41	//     refusal names the PART (embedded credentials), never the value.
42	//   - Passthrough switches are written ONE pointer field per call: a whole-document prefill would
43	//     write back a stale other switch. The API leaves an omitted pointer untouched (verified in
44	//     handleTlsPassthrough's PUT arm).
45	//   - Upstream proxy rule writes and the default write are separate single-purpose forms. A rule
46	//     body never carries "default", so the default is preserved; clearing the default is an
47	//     explicit reviewed "direct" write, never an omitted field. No ?all=true clear and no carrier
48	//     update is offered here.
49	//   - The backup config PUT is whole-document, so the confirm step snapshots the current config
50	//     and the run step re-reads and REFUSES on drift. That is a review gate, not a lock: the
51	//     limitation is stated on the review sheet and nothing here claims CAS.
52	//   - Pools are create, same-name bounds edit, and delete ONLY. No rename: Registry.Update does
53	//     not rewrite schedule references and UsingPool is not checked on that path, so a rename
54	//     would leave schedules pointing at a name nothing holds. A bounds edit preserves the pool's
55	//     current throttle in the minted body so a whole-entry Update cannot silently reset it, and
56	//     the run re-reads /api/pools and refuses on drift for the same reason.
57	//
58	// ui2SettingsWriteReviewCap bounds the review map the same way as the triage cap: enough for a
59	// few open tabs, small enough that a full map is a pileup to refuse and say, not to paper over.
60	const ui2SettingsWriteReviewCap = 8
61	
62	// ui2SettingsReview is one minted settings write held for review. The entry dies with the gate's
63	// ConfirmTTL so a stale review refuses alongside its token, and the run step spends it atomically
64	// so a double-confirm cannot dispatch twice.
65	type ui2SettingsReview struct {
66		token        string
67		gated        bool // the call dispatches through the confirmation gate with this token
68		method       string
69		callURL      string // the call's path with query, exactly as minted
70		body         []byte // the exact minted body; nil for a bodyless call
71		snapshotPath string // GET path re-read at run for drift, "" when the call is absolute-set
72		snapshot     string // canonical JSON of that read at confirm time
73		driftMsg     string
74		expires      time.Time
75	}
76	
77	// ui2SettingsCall is what a per-area parse produces: the exact gated call plus the review copy.
78	type ui2SettingsCall struct {
79		gated        bool // the API route is in the confirmation gate's set (pools); riskLocal routes mint no gate token
80		method       string
81		apiBase      string // the gated route path (no query); the mint endpoint is apiBase+"/confirm"
82		callURL      string
83		body         []byte
84		title        string
85		container    string // the settings-page container id the answer swaps into
86		consequences []string
87		nonatomic    string // non-atomic limitation line, "" when not applicable
88		snapshotPath string
89		snapshot     string // canonical JSON read at confirm, compared at run
90		driftMsg     string
91	}
92	
93	// ui2CanonicalGet reads one of the console's own GET endpoints through the internal mux and
94	// returns the canonical JSON (map keys sorted by the re-marshal), so two reads of the same state
95	// compare equal byte-for-byte.
96	func (s *Server) ui2CanonicalGet(path string) (string, error) {
97		rec := newRecorder()
98		s.mux.ServeHTTP(rec, newReq(http.MethodGet, path))
99		if rec.Code != http.StatusOK {
100			return "", fmt.Errorf("reading %s answered %d", path, rec.Code)
101		}
102		var v any
103		if err := json.Unmarshal(rec.Body.Bytes(), &v); err != nil {
104			return "", fmt.Errorf("reading %s: %v", path, err)
105		}
106		b, err := json.Marshal(v)
107		if err != nil {
108			return "", fmt.Errorf("canonicalising %s: %v", path, err)
109		}
110		return string(b), nil
111	}
112	
113	// ui2RefuseProxyUserinfo refuses a proxy URL carrying embedded credentials. The refusal names the
114	// PART, never the value - the same stance the triage page takes for secret-bearing base URLs.
115	func ui2RefuseProxyUserinfo(raw string) string {
116		u, err := url.Parse(raw)
117		if err == nil && u.User != nil {
118			return "proxy URLs with embedded credentials (user:pass@host) are not accepted on this page - " +
119				"an authenticated upstream would send those credentials with future traffic. Save an " +
120				"unauthenticated upstream here, or use the API for an authenticated one"
121		}
122		return ""
123	}
