127	func ui2ParsePassthroughCall(_ *Server, r *http.Request) (ui2SettingsCall, string) {
128		c := ui2SettingsCall{
129			apiBase:   "/api/proxy/passthrough",
130			title:     "TLS passthrough",
131			container: "settings-passthrough",
132		}
133		switch r.PostFormValue("op") {
134		case "add":
135			p := strings.TrimSpace(r.PostFormValue("pattern"))
136			if p == "" {
137				return c, "a passthrough rule needs a non-empty host pattern"
138			}
139			c.method = http.MethodPost
140			c.callURL = c.apiBase
141			c.body, _ = json.Marshal(map[string]any{"pattern": p})
142			c.consequences = []string{
143				"Future TLS connections to hosts matching \"" + p + "\" pass through UNTOUCHED: burpsy will not intercept, decrypt, or record them.",
144			}
145		case "remove":
146			p := strings.TrimSpace(r.PostFormValue("pattern"))
147			if p == "" {
148				return c, "removing a passthrough rule needs its exact host pattern"
149			}
150			c.method = http.MethodDelete
151			c.callURL = c.apiBase + "?pattern=" + url.QueryEscape(p)
152			c.consequences = []string{
153				"Future TLS connections to hosts matching \"" + p + "\" are intercepted and decrypted again.",
154			}
155		case "switch":
156			field := r.PostFormValue("field")
157			if field != "apply_out_of_scope" && field != "auto_add_on_failure" {
158				return c, "unknown passthrough switch"
159			}
160			val, err := strconv.ParseBool(r.PostFormValue("value"))
161			if err != nil {
162				return c, "a passthrough switch value must be true or false"
163			}
164			c.method = http.MethodPut
165			c.callURL = c.apiBase
166			// Exactly ONE pointer field: the API leaves an omitted switch untouched, and sending both
167			// would write back whatever state the other had when the form was drawn.
168			c.body, _ = json.Marshal(map[string]bool{field: val})
169			c.consequences = []string{ui2PassthroughSwitchCopy(field, val)}
170		default:
171			return c, "unknown passthrough operation"
172		}
173		return c, ""
174	}
175	
176	// ui2PassthroughSwitchCopy states what a coupling switch means for FUTURE traffic, on or off.
177	func ui2PassthroughSwitchCopy(field string, val bool) string {
178		switch field {
179		case "apply_out_of_scope":
180			if val {
181				return "Hosts OUTSIDE the current scope will also pass through untouched: their TLS traffic is not intercepted or recorded."
182			}
183			return "Passthrough applies inside scope only again: out-of-scope hosts are intercepted normally."
184		default: // auto_add_on_failure
185			if val {
186				return "When a client refuses burpsy's certificate, that host is added to this list AUTOMATICALLY: future connections to it bypass interception without you adding it."
187			}
188			return "A certificate refusal no longer adds hosts to the passthrough list automatically."
189		}
190	}
