192	// ui2ProxyView reads the live upstream-proxy view for review copy (the current default a removal
193	// falls back to). ok is false when the read failed: the copy must then say the current default is
194	// unavailable, never guess "direct" - an empty Default on a successful read is the only "direct".
195	func (s *Server) ui2ProxyView() (networkProxyView, bool) {
196		rec := newRecorder()
197		s.mux.ServeHTTP(rec, newReq(http.MethodGet, "/api/network/proxy"))
198		var view networkProxyView
199		if rec.Code/100 != 2 || json.Unmarshal(rec.Body.Bytes(), &view) != nil {
200			return networkProxyView{}, false
201		}
202		return view, true
203	}
