205	func ui2ParseProxyRuleCall(s *Server, r *http.Request) (ui2SettingsCall, string) {
206		c := ui2SettingsCall{
207			apiBase:   "/api/network/proxy",
208			title:     "Upstream proxy rule",
209			container: "settings-proxy",
210		}
211		switch r.PostFormValue("op") {
212		case "set":
213			pattern := strings.TrimSpace(r.PostFormValue("pattern"))
214			raw := strings.TrimSpace(r.PostFormValue("proxy"))
215			if pattern == "" {
216				return c, "a proxy rule needs a non-empty host pattern"
217			}
218			if raw == "" {
219				return c, "a proxy rule needs a proxy URL (or \"direct\")"
220			}
221			if msg := ui2RefuseProxyUserinfo(raw); msg != "" {
222				return c, msg
223			}
224			parsed, err := upstream.Parse(raw)
225			if err != nil {
226				return c, err.Error()
227			}
228			c.method = http.MethodPost
229			c.callURL = c.apiBase
230			c.body, _ = json.Marshal(map[string]any{"pattern": pattern, "proxy": raw})
231			c.consequences = []string{
232				"Future requests to hosts matching \"" + pattern + "\" are routed through " + parsed.Display() +
233					" instead of the default route. This changes where burpsy sends traffic from the moment you confirm; recorded traffic is untouched.",
234			}
235		case "remove":
236			pattern := strings.TrimSpace(r.PostFormValue("pattern"))
237			if pattern == "" {
238				return c, "removing a proxy rule needs its exact host pattern"
239			}
240			c.method = http.MethodDelete
241			c.callURL = c.apiBase + "?pattern=" + url.QueryEscape(pattern)
242			view, ok := s.ui2ProxyView()
243			if !ok {
244				c.consequences = []string{
245					"Future requests to hosts matching \"" + pattern + "\" follow the default route instead. " +
246						"The current default could not be read, so it is not stated here - re-check the upstream proxy settings before confirming.",
247				}
248			} else {
249				fallback := view.Default
250				if fallback == "" {
251					fallback = "direct"
252				}
253				c.consequences = []string{
254					"Future requests to hosts matching \"" + pattern + "\" follow the default route (" + fallback + ") instead.",
255				}
256			}
257		default:
258			return c, "unknown proxy rule operation"
259		}
260		return c, ""
261	}
