263	func ui2ParseProxyDefaultCall(s *Server, r *http.Request) (ui2SettingsCall, string) {
264		c := ui2SettingsCall{
265			apiBase:   "/api/network/proxy",
266			title:     "Upstream proxy default",
267			container: "settings-proxy",
268		}
269		if r.PostFormValue("op") != "set" {
270			return c, "unknown proxy default operation"
271		}
272		raw := strings.TrimSpace(r.PostFormValue("default"))
273		if raw == "" {
274			return c, "setting the default needs a value - enter \"direct\" to clear it"
275		}
276		if msg := ui2RefuseProxyUserinfo(raw); msg != "" {
277			return c, msg
278		}
279		parsed, err := upstream.Parse(raw)
280		if err != nil {
281			return c, err.Error()
282		}
283		c.method = http.MethodPost
284		c.callURL = c.apiBase
285		c.body, _ = json.Marshal(map[string]any{"default": raw})
286		view, ok := s.ui2ProxyView()
287		old := "which could not be read - re-check the upstream proxy settings before confirming"
288		if ok {
289			old = view.Default
290			if old == "" {
291				old = "direct"
292			}
293		}
294		if parsed.IsDirect() {
295			c.consequences = []string{
296				"Requests matching no rule go DIRECTLY to the target from now on - no upstream proxy. This clears the current default (" + old + ").",
297			}
298		} else {
299			c.consequences = []string{
300				"Requests matching no rule are routed through " + parsed.Display() + " from now on (replacing " + old + ").",
301			}
302		}
303		return c, ""
304	}
