306	func ui2ParseBackupCall(s *Server, r *http.Request) (ui2SettingsCall, string) {
307		c := ui2SettingsCall{
308			apiBase:   "/api/backup/config",
309			title:     "Automatic backup",
310			container: "settings-backup",
311			// The whole-document PUT overwrites every field, so the run re-reads and refuses drift.
312			// This is a review gate, not a lock - said on the sheet, never claimed as CAS.
313			snapshotPath: "/api/backup/config",
314			driftMsg:     "the backup settings changed between your review and this confirmation - review the current settings and save again",
315			nonatomic: "Not atomic: the settings are re-read when you confirm and this save is refused if they changed " +
316				"since your review, but a change landing inside the check-and-save instant is not locked out. " +
317				"This is a review gate, not a transaction.",
318		}
319		if r.PostFormValue("op") != "set" {
320			return c, "unknown backup operation"
321		}
322		interval, err := strconv.Atoi(strings.TrimSpace(r.PostFormValue("interval_minutes")))
323		if err != nil {
324			return c, "the backup interval must be whole minutes (0 turns automatic backup off)"
325		}
326		if interval < 0 {
327			return c, "the backup interval cannot be negative (0 turns automatic backup off)"
328		}
329		retention, err := strconv.Atoi(strings.TrimSpace(r.PostFormValue("retention")))
330		if err != nil {
331			return c, "the retention must be a whole number of snapshots (0 takes the default, negative keeps everything)"
332		}
333		dir := strings.TrimSpace(r.PostFormValue("dir"))
334		deleteOnShutdown := r.PostFormValue("delete_on_shutdown") != ""
335		if s.persist == nil {
336			return c, "this instance has no project database, so backup settings cannot be saved"
337		}
338		// The effective directory is stated, never blank: an empty dir means "beside the live
339		// database", the same fallback the backup run and the shutdown sweep use (api_backup.go,
340		// deleteBackupsOnShutdown). If that fallback cannot be grounded, the review is refused
341		// rather than rendered with a guess.
342		effectiveDir := dir
343		if effectiveDir == "" {
344			live := s.persist.Path()
345			if live == "" {
346				return c, "no directory is set and the live database has no path, so which directory backups " +
347					"would use cannot be shown - set a directory explicitly"
348			}
349			effectiveDir = filepath.Dir(live)
350		}
351		c.method = http.MethodPut
352		c.callURL = c.apiBase
353		c.body, _ = json.Marshal(map[string]any{
354			"interval_minutes":   interval,
355			"dir":                dir,
356			"retention":          retention,
357			"delete_on_shutdown": deleteOnShutdown,
358		})
359		if interval == 0 {
360			c.consequences = append(c.consequences,
361				"Automatic backup turns OFF: the managed schedule is removed. No existing backup files are deleted by this change.")
362		} else {
363			c.consequences = append(c.consequences,
364				fmt.Sprintf("Every %d minutes burpsy writes a full database snapshot into %s. The managed schedule is created or updated to match; the first snapshot is one interval from now, not immediate.", interval, effectiveDir))
365		}
366		switch {
367		case retention == 0:
368			c.consequences = append(c.consequences, "Retention: the default keep-count applies when a backup runs.")
369		case retention < 0:
370			c.consequences = append(c.consequences, "Retention: EVERY snapshot is kept - nothing is pruned, so the directory grows until you prune it.")
371		default:
372			c.consequences = append(c.consequences,
373				fmt.Sprintf("Retention: only the newest %d snapshots are kept; older ones are pruned when a backup runs.", retention))
374		}
375		if dir == "" {
376			c.consequences = append(c.consequences,
377				"No directory is set: snapshots are written beside the live database ("+effectiveDir+"). That cannot fail for a missing path, but it is the worst place for a backup if the disk is what fails.")
378		}
379		if deleteOnShutdown {
380			c.consequences = append(c.consequences,
381				"On a CLEAN SHUTDOWN burpsy deletes every automatic-backup file in "+effectiveDir+". A crash leaves them in place; your own files in that directory are never matched.")
382		}
383		return c, ""
384	}
