386	func ui2ParsePoolsCall(s *Server, r *http.Request) (ui2SettingsCall, string) {
387		c := ui2SettingsCall{
388			gated:     true, // /api/pools and /api/pools/ are riskScope
389			apiBase:   "/api/pools",
390			title:     "Resource pools",
391			container: "settings-pools",
392		}
393		view := s.ui2PoolsView()
394		switch r.PostFormValue("op") {
395		case "create":
396			name := strings.TrimSpace(r.PostFormValue("name"))
397			mc, dm, msg := ui2ParsePoolBounds(r)
398			if msg != "" {
399				return c, msg
400			}
401			c.method = http.MethodPost
402			c.callURL = c.apiBase
403			// No throttle key: a pool created here has automatic throttling OFF, and the review says
404			// so rather than implying the field does not exist.
405			c.body, _ = json.Marshal(map[string]any{"name": name, "max_concurrent": mc, "delay_ms": dm})
406			c.consequences = []string{
407				fmt.Sprintf("Tools can now be pointed at pool %q: at most %d requests in flight, %d ms between requests, for runs started after you confirm.", name, mc, dm),
408				"Automatic throttling: OFF - this form does not set it. Edit the pool over the API if you need it.",
409			}
410		case "edit":
411			name := strings.TrimSpace(r.PostFormValue("name"))
412			mc, dm, msg := ui2ParsePoolBounds(r)
413			if msg != "" {
414				return c, msg
415			}
416			var curThrottle any
417			found := false
418			for i := range view.Pools {
419				if view.Pools[i].Name == name {
420					curThrottle = view.Pools[i].Throttle
421					found = true
422					break
423				}
424			}
425			if !found {
426				return c, "no pool named \"" + name + "\" is saved - the page may be stale; reload it"
427			}
428			// Same-name bounds edit ONLY: the body's name restates the path's, so no rename can be
429			// expressed (a rename dangles schedule references - Registry.Update does not rewrite them).
430			// The current throttle is carried into the body because Update replaces the whole entry:
431			// omitting it would silently turn a throttle the operator never touched off.
432			body := map[string]any{"name": name, "max_concurrent": mc, "delay_ms": dm}
433			throttleCopy := "Automatic throttling: unchanged (off)."
434			if curThrottle != nil {
435				body["throttle"] = curThrottle
436				throttleCopy = "Automatic throttling: preserved unchanged (on) - the exact current setting is carried in the call above."
437			}
438			c.method = http.MethodPut
439			c.callURL = c.apiBase + "/" + url.PathEscape(name)
440			c.body, _ = json.Marshal(body)
441			c.snapshotPath = "/api/pools"
442			c.driftMsg = "the pools changed between your review and this confirmation - review the current pools and save again"
443			c.nonatomic = "Not atomic: the pools are re-read when you confirm and this save is refused if they changed " +
444				"since your review, but a change landing inside the check-and-save instant is not locked out. " +
445				"This is a review gate, not a transaction."
446			c.consequences = []string{
447				fmt.Sprintf("Pool %q now allows at most %d requests in flight, %d ms between requests, for runs started after you confirm. The pool's name and identity do not change.", name, mc, dm),
448				throttleCopy,
449			}
450		case "delete":
451			name := strings.TrimSpace(r.PostFormValue("name"))
452			if name == "" {
453				return c, "deleting a pool needs its name"
454			}
455			c.method = http.MethodDelete
456			c.callURL = c.apiBase + "/" + url.PathEscape(name)
457			c.consequences = []string{
458				"Pool \"" + name + "\" is deleted. Tools can no longer be pointed at it; runs already in flight keep the bounds they started with.",
459			}
460			if used := view.InUse[name]; len(used) > 0 {
461				c.consequences = append(c.consequences,
462					"It currently bounds schedule(s): "+strings.Join(used, ", ")+" - the API refuses this delete while that is true, and you will see that refusal.")
463			}
464		default:
465			return c, "unknown pools operation"
466		}
467		return c, ""
468	}
