470	// ui2PoolsView reads the live pools view for edit/delete review copy and throttle preservation.
471	func (s *Server) ui2PoolsView() poolsView {
472		rec := newRecorder()
473		s.mux.ServeHTTP(rec, newReq(http.MethodGet, "/api/pools"))
474		var view poolsView
475		_ = json.Unmarshal(rec.Body.Bytes(), &view)
476		return view
477	}
