479	// ui2ParsePoolBounds reads and validates the two bounds fields shared by create and edit. The
480	// semantic ceilings live in pool.Validate; here only garbage is refused, so the API stays the
481	// authority on what a bound may be.
482	func ui2ParsePoolBounds(r *http.Request) (int, int, string) {
483		mc, err := strconv.Atoi(strings.TrimSpace(r.PostFormValue("max_concurrent")))
484		if err != nil {
485			return 0, 0, "max concurrent requests must be a whole number"
486		}
487		dm, err := strconv.Atoi(strings.TrimSpace(r.PostFormValue("delay_ms")))
488		if err != nil {
489			return 0, 0, "the delay must be whole milliseconds"
490		}
491		return mc, dm, ""
492	}
