494	var ui2SettingsWriteParsers = map[string]func(*Server, *http.Request) (ui2SettingsCall, string){
495		"passthrough":   ui2ParsePassthroughCall,
496		"proxy-rule":    ui2ParseProxyRuleCall,
497		"proxy-default": ui2ParseProxyDefaultCall,
498		"backup":        ui2ParseBackupCall,
499		"pools":         ui2ParsePoolsCall,
500	}
