502	// ui2SettingsWriteContainer maps a write area to the settings-page container its answers swap
503	// into: the two proxy write areas share the one proxy section.
504	func ui2SettingsWriteContainer(area string) string {
505		return "settings-" + ui2SettingsWriteFragArea(area)
506	}
507	
508	// ui2SettingsWriteFragArea maps a write area to the fragment that re-renders after its run:
509	// both proxy write areas load the one proxy section.
510	func ui2SettingsWriteFragArea(area string) string {
511		if area == "proxy-rule" || area == "proxy-default" {
512			return "proxy"
513		}
514		return area
515	}
516	
517	// ---- confirm / run ----------------------------------------------------------------------------
518	
519	// handleUI2SettingsWrite serves POST /ui2/settings/write/{area}/{action}: confirm mints and
