532	func (s *Server) ui2SettingsWriteConfirm(w http.ResponseWriter, r *http.Request) {
533		area := r.PathValue("area")
534		parse, ok := ui2SettingsWriteParsers[area]
535		if !ok {
536			http.Error(w, "unknown settings area", http.StatusNotFound)
537			return
538		}
539		fail := func(msg string) {
540			model := map[string]any{"error": msg, "area": area, "container": ui2SettingsWriteContainer(area), "frag": ui2SettingsWriteFragArea(area)}
541			ui2Fragment(w, r, "burpsy /ui2/ — Settings", "settings", ui2Exec("settings_write_confirm.html", model))
542		}
543		_ = r.ParseForm()
544		call, errMsg := parse(s, r)
545		if errMsg != "" {
546			fail(errMsg)
547			return
548		}
549		if call.snapshotPath != "" {
550			snap, err := s.ui2CanonicalGet(call.snapshotPath)
551			if err != nil {
552				fail("could not read the current state to review against: " + err.Error())
553				return
554			}
555			call.snapshot = snap
556		}
557		// A gated call's token comes from the confirmation gate and binds the exact method, path,
558		// query and canonical body. An ungated (riskLocal) call gets a ui2-local one-use handle -
559		// the exact-bytes property is the held entry itself, dispatched verbatim and spent once.
560		token := ""
561		if call.gated {
562			mintCall := map[string]any{"method": call.method, "url": call.callURL}
563			if call.body != nil {
564				mintCall["body"] = string(call.body)
565			}
566			rawMint, _ := json.Marshal(mintCall)
567			mintReq := newReq(http.MethodPost, call.apiBase+"/confirm")
568			mintReq.Header.Set("Content-Type", "application/json")
569			mintReq.Body = ioNopCloser(strings.NewReader(string(rawMint)))
570			mintRec := newRecorder()
571			s.confirmMux.ServeHTTP(mintRec, mintReq)
572			var minted struct {
573				Token string `json:"token"`
574			}
575			if mintRec.Code != http.StatusOK {
576				fail("the confirmation gate refused to mint a review (" + http.StatusText(mintRec.Code) + ") - try again")
577				return
578			}
579			if err := json.Unmarshal(mintRec.Body.Bytes(), &minted); err != nil || minted.Token == "" {
580				fail("the confirmation gate refused to mint a review - try again")
581				return
582			}
583			token = minted.Token
584		} else {
585			local, err := randomHex(16)
586			if err != nil {
587				fail("review token: " + err.Error())
588				return
589			}
590			token = local
591		}
592		id, err := randomHex(16)
593		if err != nil {
594			fail("review id: " + err.Error())
595			return
596		}
597		// Sweep expired entries on issue, then refuse when the map is still full - a full map means a
598		// pileup of open reviews, which is a thing to say, not to silently drop.
599		now := time.Now()
600		s.ui2SettingsWriteReviews.Range(func(k, v any) bool {
601			if e, ok := v.(ui2SettingsReview); ok && now.After(e.expires) {
602				s.ui2SettingsWriteReviews.Delete(k)
603			}
604			return true
605		})
606		count := 0
607		s.ui2SettingsWriteReviews.Range(func(_, _ any) bool { count++; return true })
608		if count >= ui2SettingsWriteReviewCap {
609			fail("too many reviews are open at once - confirm or let some expire, then try again")
610			return
611		}
612		s.ui2SettingsWriteReviews.Store(id, ui2SettingsReview{
613			token:        token,
614			gated:        call.gated,
615			method:       call.method,
616			callURL:      call.callURL,
617			body:         call.body,
618			snapshotPath: call.snapshotPath,
619			snapshot:     call.snapshot,
620			driftMsg:     call.driftMsg,
621			expires:      now.Add(ConfirmTTL),
622		})
623		// The projection is derived from the exact held bytes - parse and re-marshal so the sheet
624		// shows what the token binds, never a second serialization of the form.
625		projection := call.method + " " + call.callURL
626		if call.body != nil {
627			var m map[string]any
628			if err := json.Unmarshal(call.body, &m); err == nil {
629				if pretty, err := json.MarshalIndent(m, "", "  "); err == nil {
630					projection += "\n" + string(pretty)
631				} else {
632					projection += "\n" + string(call.body)
633				}
634			} else {
635				projection += "\n" + string(call.body)
636			}
637		}
638		ui2Fragment(w, r, "burpsy /ui2/ — Settings", "settings", ui2Exec("settings_write_confirm.html", map[string]any{
639			"area":         area,
640			"container":    call.container,
641			"area_title":   call.title,
642			"review_id":    id,
643			"token":        token,
644			"projection":   projection,
645			"consequences": call.consequences,
646			"nonatomic":    call.nonatomic,
647			"frag":         ui2SettingsWriteFragArea(area),
648		}))
649	}
