651	func (s *Server) ui2SettingsWriteRun(w http.ResponseWriter, r *http.Request) {
652		area := r.PathValue("area")
653		if _, ok := ui2SettingsWriteParsers[area]; !ok {
654			http.Error(w, "unknown settings area", http.StatusNotFound)
655			return
656		}
657		fail := func(msg string) {
658			model := map[string]any{"error": msg, "area": area, "container": ui2SettingsWriteContainer(area), "frag": ui2SettingsWriteFragArea(area)}
659			ui2Fragment(w, r, "burpsy /ui2/ — Settings", "settings", ui2Exec("settings_write_confirm.html", model))
660		}
661		_ = r.ParseForm()
662		// The entry is deleted on ANY spend attempt (unknown id, stale, token mismatch, drift,
663		// dispatch result) so nothing here is replayable.
664		v, ok := s.ui2SettingsWriteReviews.LoadAndDelete(r.PostFormValue("review_id"))
665		entry, isReview := v.(ui2SettingsReview)
666		if !ok || !isReview {
667			fail("that review is unknown or was already used - review the change again")
668			return
669		}
670		if time.Now().After(entry.expires) {
671			fail("that review expired with the confirmation window - review the change again")
672			return
673		}
674		// Both sides are 128-bit random values; compare in constant time anyway so the check never
675		// becomes an oracle if the id scheme ever changes.
676		if subtle.ConstantTimeCompare([]byte(entry.token), []byte(r.PostFormValue("token"))) != 1 {
677			fail("that review does not match this confirmation - review the change again")
678			return
679		}
680		if entry.snapshotPath != "" {
681			now, err := s.ui2CanonicalGet(entry.snapshotPath)
682			if err != nil {
683				fail("could not re-read the current state to confirm against: " + err.Error())
684				return
685			}
686			if now != entry.snapshot {
687				fail(entry.driftMsg)
688				return
689			}
690		}
691		// Dispatch the held call verbatim. Re-marshaling here could produce bytes the review did not
692		// show. A gated call goes through the guarded chain with its gate token in the confirm
693		// header; an ungated (riskLocal) call is answered by the internal mux directly.
694		req := newReq(entry.method, entry.callURL)
695		if entry.body != nil {
696			req.Header.Set("Content-Type", "application/json")
697			req.Body = ioNopCloser(strings.NewReader(string(entry.body)))
698		}
699		rec := newRecorder()
700		if entry.gated {
701			req.Header.Set(ConfirmHeader, entry.token)
702			req.Host = "127.0.0.1"
703			req.Header.Set("Origin", "http://127.0.0.1")
704			s.guarded.ServeHTTP(rec, req)
705		} else {
706			s.mux.ServeHTTP(rec, req)
707		}
708		if rec.Code == http.StatusPreconditionRequired {
709			fail("confirmation required (428) - the review and the dispatch disagree; review again")
710			return
711		}
712		if rec.Code != http.StatusOK && rec.Code != http.StatusCreated {
713			fail("the settings API refused the change: " + truncateForDisplay(strings.TrimSpace(rec.Body.String()), 200))
714			return
715		}
716		s.handleUI2SettingsWriteArea(w, r, area)
717	}
