		if err := requestJSON(w, r, nil).Decode(&body); err != nil {
			http.Error(w, "Body must be JSON: {\"bind\": \"host:port\", \"redirect_host\": …, \"redirect_port\": …, \"force_tls\": …, \"invisible\": …}", http.StatusBadRequest)
