46	// ui2ProxyCall is what a per-area parser produces: the exact call plus its review copy.
47	type ui2ProxyCall struct {
48		area         string
49		method       string
50		callURL      string
51		body         []byte
52		title        string
53		consequences []string
54		snap         func(*Server) (string, error) // state the call overwrites; nil when absolute
55		driftMsg     string
56	}
57	
58	// ui2ProxyNeedsGate derives the gate requirement from the API route's manifest risk class. An
59	// unknown route fails closed (gated): its mint then fails and the review is refused.
60	func ui2ProxyNeedsGate(callURL string) bool {
61		path := callURL
62		if i := strings.IndexByte(path, '?'); i >= 0 {
63			path = path[:i]
64		}
65		_, risk, ok := routeRiskFor(path)
66		return !ok || needsConfirmation(risk)
67	}
68	
69	// ui2ProxyCanonicalField reads one console GET and returns the canonical JSON of one top-level
70	// field: counters and traffic-driven figures sit beside the state and must not read as drift.
71	func (s *Server) ui2ProxyCanonicalField(path, field string) (string, error) {
72		rec := newRecorder()
73		s.mux.ServeHTTP(rec, newReq(http.MethodGet, path))
74		if rec.Code != http.StatusOK {
75			return "", fmt.Errorf("reading %s answered %d", path, rec.Code)
76		}
77		var m map[string]any
78		if err := json.Unmarshal(rec.Body.Bytes(), &m); err != nil {
79			return "", fmt.Errorf("reading %s: %v", path, err)
80		}
81		b, err := json.Marshal(m[field])
82		if err != nil {
83			return "", err
84		}
85		return string(b), nil
86	}
87	
88	func ui2ProxySnap(path, field string) func(*Server) (string, error) {
89		return func(s *Server) (string, error) { return s.ui2ProxyCanonicalField(path, field) }
90	}
91	
92	// ui2ProxyRenderers re-render an area's page after a run (or a refusal), with a note.
93	var ui2ProxyRenderers = map[string]func(*Server, http.ResponseWriter, *http.Request, ui2ProxyNote){
94		"listeners":     (*Server).renderUI2ProxyListeners,
95		"options":       (*Server).renderUI2ProxyOptions,
96		"match-replace": (*Server).renderUI2MatchReplaceSaved,
97	}
98	
99	type ui2ProxyNote struct {
100		OK    string
101		Error string
102	}
103	
104	// ui2ProxyReviewFail renders a refusal into the review slot.
105	func ui2ProxyReviewFail(w http.ResponseWriter, r *http.Request, view, msg string) {
106		ui2Fragment(w, r, "burpsy /ui2/ — Proxy", view, ui2Exec("proxy_review.html", map[string]any{"error": msg}))
107	}
108	
109	// ui2ProxyConfirm holds one call for review and renders the review sheet.
110	func (s *Server) ui2ProxyConfirm(w http.ResponseWriter, r *http.Request, view string, call ui2ProxyCall) {
111		fail := func(msg string) { ui2ProxyReviewFail(w, r, view, msg) }
112		snapshot := ""
113		if call.snap != nil {
114			snap, err := call.snap(s)
115			if err != nil {
116				fail("could not read the current state to review against: " + err.Error())
117				return
118			}
119			snapshot = snap
120		}
121		gated := ui2ProxyNeedsGate(call.callURL)
122		token := ""
123		if gated {
124			path := call.callURL
125			if i := strings.IndexByte(path, '?'); i >= 0 {
126				path = path[:i]
127			}
128			tok, _, errText := s.ui2MintConfirm(path, call.method, call.callURL, call.body)
129			if errText != "" || tok == "" {
130				fail("the confirmation gate refused to mint a review - try again")
131				return
132			}
133			token = tok
134		} else {
135			local, err := randomHex(16)
136			if err != nil {
137				fail("review token: " + err.Error())
138				return
139			}
140			token = local
141		}
142		id, err := randomHex(16)
143		if err != nil {
144			fail("review id: " + err.Error())
145			return
146		}
147		now := time.Now()
148		count := 0
149		s.ui2ProxyReviews.Range(func(k, v any) bool {
150			if e, ok := v.(ui2ProxyReview); ok && now.After(e.expires) {
151				s.ui2ProxyReviews.Delete(k)
152			} else {
153				count++
154			}
155			return true
