231	// ui2ProxyRun spends a held review and dispatches it, then re-renders the area's page.
232	func (s *Server) ui2ProxyRun(w http.ResponseWriter, r *http.Request, area string) {
233		render := ui2ProxyRenderers[area]
234		fail := func(msg string) { render(s, w, r, ui2ProxyNote{Error: msg}) }
235		_ = r.ParseForm()
236		v, ok := s.ui2ProxyReviews.LoadAndDelete(r.PostFormValue("review_id"))
237		entry, isReview := v.(ui2ProxyReview)
238		if !ok || !isReview || entry.area != area {
239			fail("that review is unknown or was already used - review the change again")
240			return
241		}
242		if time.Now().After(entry.expires) {
243			fail("that review expired with the confirmation window - review the change again")
244			return
245		}
246		if subtle.ConstantTimeCompare([]byte(entry.token), []byte(r.PostFormValue("token"))) != 1 {
247			fail("that review does not match this confirmation - review the change again")
248			return
249		}
250		if entry.snap != nil {
251			now, err := entry.snap(s)
252			if err != nil {
253				fail("could not re-read the current state to confirm against: " + err.Error())
254				return
255			}
256			if now != entry.snapshot {
257				fail(entry.driftMsg)
258				return
259			}
260		}
261		req := newReq(entry.method, entry.callURL)
262		if entry.body != nil {
263			req.Header.Set("Content-Type", "application/json")
264			req.Body = ioNopCloser(strings.NewReader(string(entry.body)))
265		}
266		rec := newRecorder()
267		if entry.gated {
268			req.Header.Set(ConfirmHeader, entry.token)
269			req.Host = "127.0.0.1"
270			req.Header.Set("Origin", "http://127.0.0.1")
271			s.guarded.ServeHTTP(rec, req)
272		} else {
273			s.mux.ServeHTTP(rec, req)
274		}
275		if rec.Code/100 != 2 {
276			fail("the API refused the change: " + truncateForDisplay(strings.TrimSpace(rec.Body.String()), 300))
277			return
278		}
279		render(s, w, r, ui2ProxyNote{OK: "Saved: " + entry.method + " " + entry.callURL + " answered " + strconv.Itoa(rec.Code) + "."})
280	}
